<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel | Fiscalização de Obras</title><link rel="stylesheet" href="/assets/css/app.css"></head>
<body><header class="topbar"><div><strong>Fiscalização de Obras</strong><small>Painel multi-condomínio</small></div><div><?= htmlspecialchars($user['name']) ?> · <a href="/logout">Sair</a></div></header><main class="container"><section class="hero"><h1>Meus empreendimentos</h1><p>Selecione um condomínio para acompanhar obras, fiscalizações e pendências.</p></section><section class="cards"><?php foreach ($condominiums as $c): ?><article class="card"><h2><?= htmlspecialchars($c['name']) ?></h2><div class="metrics"><span><b><?= (int)$c['in_progress'] ?></b> Em andamento</span><span><b><?= (int)$c['authorized'] ?></b> Autorizadas</span><span><b><?= (int)$c['notified'] ?></b> Notificadas</span><span><b><?= (int)$c['embargoed'] ?></b> Embargadas</span></div><a class="button" href="/?condo=<?= (int)$c['id'] ?>">Acessar condomínio</a></article><?php endforeach; ?><?php if (!$condominiums): ?><div class="empty">Nenhum condomínio vinculado ao seu usuário.</div><?php endif; ?></section></main></body></html>
